// Generated by Phantom Workspace from a canvas zone. shots.json is rewritten
// on every export; edit this file freely to change the look.
import React from 'react';
import { AbsoluteFill, Img, OffthreadVideo, Series, interpolate, staticFile, useCurrentFrame } from 'remotion';
import storyboard from './shots.json';

type Shot = { title: string; kind: 'image' | 'video' | 'link'; file: string | null; note: string; frames: number; startFrom: number; url: string | null };

const Caption: React.FC<{ shot: Shot; index: number }> = ({ shot, index }) => {
  const frame = useCurrentFrame();
  const opacity = interpolate(frame, [0, 10], [0, 1], { extrapolateRight: 'clamp' });
  return <div style={{ position: 'absolute', left: 64, right: 64, bottom: 56, opacity, color: 'white', fontFamily: 'Inter, system-ui, sans-serif', textShadow: '0 2px 12px #000c' }}>
    <div style={{ fontSize: 26, opacity: .7 }}>Toma {index + 1}</div>
    <div style={{ fontSize: 44, fontWeight: 600 }}>{shot.title}</div>
    {shot.note ? <div style={{ fontSize: 30, marginTop: 8, opacity: .9 }}>{shot.note}</div> : null}
  </div>;
};

const Frame: React.FC<{ shot: Shot; index: number }> = ({ shot, index }) => {
  const frame = useCurrentFrame();
  const scale = interpolate(frame, [0, shot.frames], [1, 1.06]);
  return <AbsoluteFill style={{ backgroundColor: '#0b0910' }}>
    {shot.file && shot.kind === 'video' ? <OffthreadVideo src={staticFile(shot.file)} startFrom={shot.startFrom} style={{ width: '100%', height: '100%', objectFit: 'contain' }} />
      : shot.file ? <Img src={staticFile(shot.file)} style={{ width: '100%', height: '100%', objectFit: 'contain', transform: `scale(${scale})` }} />
      : <AbsoluteFill style={{ justifyContent: 'center', alignItems: 'center', color: '#a69bb7', fontSize: 36, fontFamily: 'Inter, system-ui, sans-serif' }}>{shot.url}</AbsoluteFill>}
    {storyboard.captions ? <Caption shot={shot} index={index} /> : null}
  </AbsoluteFill>;
};

export const Storyboard: React.FC = () => <Series>
  {(storyboard.shots as Shot[]).map((shot, index) => <Series.Sequence key={index} durationInFrames={shot.frames}><Frame shot={shot} index={index} /></Series.Sequence>)}
</Series>;
